<?php section('arquitetura', 'Por trás das soluções', '05 / architecture/overview.svg'); ?>
<p class="section-intro">Uma solução organizada fica mais fácil de entender, manter e ampliar. Estes diagramas são exemplos educativos de como as partes de um site ou sistema podem trocar informações, não representam projetos já entregues.</p>
<div class="architecture-shell"><div class="architecture-tabs" role="tablist" aria-label="Arquiteturas"><?php foreach($portfolio['architectures'] as $i=>$arch): ?><button type="button" role="tab" aria-selected="<?= $i===0?'true':'false' ?>" class="<?= $i===0?'selected':'' ?>" data-architecture="<?= e($arch['id']) ?>"><?= e($arch['name']) ?></button><?php endforeach; ?></div><?php foreach($portfolio['architectures'] as $i=>$arch): ?><div class="architecture-view" data-architecture-view="<?= e($arch['id']) ?>" <?= $i?'hidden':'' ?>><p><?= e($arch['description']) ?> <span class="category-pill">EXEMPLO EDUCACIONAL</span></p><div class="diagram-flow" role="list" aria-label="<?= e($arch['description']) ?>"><?php foreach($arch['nodes'] as $j=>$node): ?><?php if($j>0): ?><span class="flow-arrow" aria-hidden="true">→</span><?php endif; ?><button type="button" class="diagram-node<?= $j===0?' selected':'' ?>" role="listitem" data-node="<?= e($arch['id'].'-'.$j) ?>"><?= e($node['name']) ?></button><?php endforeach; ?></div><div class="node-info" data-node-info><span class="node-dot"></span><div><strong><?= e($arch['nodes'][0]['name']) ?></strong><p><?= e($arch['nodes'][0]['responsibility']) ?> <?= e($arch['nodes'][0]['benefit']) ?></p></div></div><script type="application/json" data-architecture-data="<?= e($arch['id']) ?>"><?= json_encode($arch['nodes'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP|JSON_UNESCAPED_UNICODE) ?></script><ol class="sr-only"><?php foreach($arch['nodes'] as $node): ?><li><?= e($node['name']) ?>. <?= e($node['responsibility']) ?> <?= e($node['benefit']) ?></li><?php endforeach; ?></ol></div><?php endforeach; ?></div>
